//! Regression tests for ESP-at-nuclei and static RPA polarizability vs
//! PySCF references in `testdata/reference/{mol}_{basis}_rpa_props.json`.
//!
//! References are generated by `scripts/gen_pyscf_rpa_props.py`.

use ferric_core::basis;
use ferric_core::mol::Molecule;
use ferric_core::parallel::ParallelContext;
use ferric_integrals::basis_bridge::PreparedBasis;
use ferric_integrals::operator::Operator;
use ferric_rpa::properties::{esp_at_atoms, pdep_polarizability_static};
use ferric_rpa::PdepRpaConfig;
use ferric_scf::rhf::{solve_rhf, RhfConfig};
use ferric_scf::screening::SchwarzBounds;
use serde::Deserialize;

#[derive(Deserialize)]
struct PropsRef {
    esp_at_atoms: Vec<f64>,
    alpha_tensor: [[f64; 3]; 3],
    alpha_iso: f64,
}

fn load_ref(path: &str) -> PropsRef {
    let s = std::fs::read_to_string(path)
        .unwrap_or_else(|_| panic!("missing ref: {path}"));
    serde_json::from_str(&s).unwrap()
}

fn setup_h2_ccpvdz() -> (
    Molecule,
    PreparedBasis,
    PreparedBasis,
    Operator,
    ferric_scf::ScfResult,
) {
    let xyz = "2\nH2 1.4 Bohr\nH 0 0 0\nH 0 0 0.74083\n";
    let mol = Molecule::parse_xyz(xyz, 0, 1).unwrap();
    let obs_bs = basis::bundled("cc-pvdz").unwrap();
    let dfbs_bs = basis::bundled("cc-pvdz-ri").unwrap();
    let op = Operator::coulomb();
    let obs = PreparedBasis::new(&mol, &obs_bs).unwrap();
    let dfbs = PreparedBasis::new(&mol, &dfbs_bs).unwrap();
    let ctx = ParallelContext::default();
    let bounds = SchwarzBounds::compute(op, &obs).unwrap();
    let rhf = solve_rhf(&ctx, &mol, &obs, op, &bounds, &RhfConfig::default()).unwrap();
    (mol, obs, dfbs, op, rhf)
}

fn setup_h2o_ccpvdz() -> (
    Molecule,
    PreparedBasis,
    PreparedBasis,
    Operator,
    ferric_scf::ScfResult,
) {
    let mol = Molecule::load_xyz("../../testdata/molecules/water.xyz").unwrap();
    let obs_bs = basis::bundled("cc-pvdz").unwrap();
    let dfbs_bs = basis::bundled("cc-pvdz-ri").unwrap();
    let op = Operator::coulomb();
    let obs = PreparedBasis::new(&mol, &obs_bs).unwrap();
    let dfbs = PreparedBasis::new(&mol, &dfbs_bs).unwrap();
    let ctx = ParallelContext::default();
    let bounds = SchwarzBounds::compute(op, &obs).unwrap();
    let rhf = solve_rhf(&ctx, &mol, &obs, op, &bounds, &RhfConfig::default()).unwrap();
    (mol, obs, dfbs, op, rhf)
}

#[test]
fn h2_polarizability_matches_pyscf_direct_rpa() {
    let r = load_ref("../../testdata/reference/h2_cc-pvdz_rpa_props.json");
    let (mol, obs, dfbs, op, rhf) = setup_h2_ccpvdz();

    let mut cfg = PdepRpaConfig::default();
    cfg.frozen_core = 0;
    cfg.trunc_thresh = 0.0;
    cfg.davidson_conv_thresh = 1e-10;

    let pol = pdep_polarizability_static(&mol, &obs, &dfbs, &rhf, op, &cfg).unwrap();

    // Component-by-component within 5e-3 a.u. or 2% (whichever looser).
    for i in 0..3 {
        for j in 0..3 {
            let got = pol.tensor[i][j];
            let exp = r.alpha_tensor[i][j];
            let abs = (got - exp).abs();
            let rel = abs / exp.abs().max(1e-8);
            assert!(
                abs < 5e-3 || rel < 0.02,
                "α[{i},{j}]: ferric={got:.6}, pyscf={exp:.6} (Δ={abs:.2e}, rel={rel:.2e})"
            );
        }
    }
    // Isotropic must be tight (3e-3).
    let abs_iso = (pol.iso - r.alpha_iso).abs();
    assert!(
        abs_iso < 3e-3,
        "α_iso: ferric={:.6}, pyscf={:.6} (Δ={:.2e})",
        pol.iso, r.alpha_iso, abs_iso
    );
}

#[test]
fn h2_esp_matches_pyscf() {
    let r = load_ref("../../testdata/reference/h2_cc-pvdz_rpa_props.json");
    let (mol, obs, _dfbs, _op, rhf) = setup_h2_ccpvdz();
    let v = esp_at_atoms(&mol, &obs, rhf.density_r()).unwrap();
    assert_eq!(v.len(), r.esp_at_atoms.len());
    for (a, (got, exp)) in v.iter().zip(r.esp_at_atoms.iter()).enumerate() {
        let d = (got - exp).abs();
        assert!(
            d < 1e-4,
            "ESP atom {a}: ferric={got:.6}, pyscf={exp:.6} (Δ={d:.2e})"
        );
    }
}

#[test]
fn h2o_polarizability_and_esp_match_pyscf() {
    let r = load_ref("../../testdata/reference/h2o_cc-pvdz_rpa_props.json");
    let (mol, obs, dfbs, op, rhf) = setup_h2o_ccpvdz();

    // ESP
    let v = esp_at_atoms(&mol, &obs, rhf.density_r()).unwrap();
    for (a, (got, exp)) in v.iter().zip(r.esp_at_atoms.iter()).enumerate() {
        let d = (got - exp).abs();
        assert!(
            d < 1e-4,
            "ESP atom {a}: ferric={got:.6}, pyscf={exp:.6} (Δ={d:.2e})"
        );
    }

    // Polarizability
    let mut cfg = PdepRpaConfig::default();
    cfg.frozen_core = 0;
    cfg.trunc_thresh = 0.0;
    cfg.davidson_conv_thresh = 1e-10;
    let pol = pdep_polarizability_static(&mol, &obs, &dfbs, &rhf, op, &cfg).unwrap();
    for i in 0..3 {
        for j in 0..3 {
            let got = pol.tensor[i][j];
            let exp = r.alpha_tensor[i][j];
            let abs = (got - exp).abs();
            let rel = abs / exp.abs().max(1e-8);
            assert!(
                abs < 5e-3 || rel < 0.02,
                "α[{i},{j}]: ferric={got:.6}, pyscf={exp:.6} (Δ={abs:.2e}, rel={rel:.2e})"
            );
        }
    }
    let abs_iso = (pol.iso - r.alpha_iso).abs();
    assert!(
        abs_iso < 5e-3 || abs_iso / r.alpha_iso < 0.02,
        "α_iso: ferric={:.6}, pyscf={:.6} (Δ={:.2e})",
        pol.iso, r.alpha_iso, abs_iso
    );
}
